erDiagram
  CUSTOMER ||--o{ ORDER : places
  ORDER {
    string id
  }

radar-beta
  title Skills
  axis speed["Speed"], power["Power"], range["Range"]
  curve now["Current"]{4, 3, 5}
  curve goal["Target"]{5, 5, 4}
  max 5

requirementDiagram
  requirement fast {
    id: 1
    text: Respond within 100ms
    risk: high
    verifymethod: test
  }
  element benchmark {
    type: "test"
  }
  benchmark - verifies -> fast

classDiagram
  class Renderer {
    <<abstract>>
    +render(source) string
  }
  class SVGRenderer {
    +render(source) string
  }
  class RenderPipeline {
    +run(source) string
  }
  Renderer <|-- SVGRenderer
  RenderPipeline *-- SVGRenderer : owns

erDiagram
  CUSTOMER {
    string id PK
    string email
  }
  ORDER {
    string id PK
    date created
  }
  LINE_ITEM {
    string id PK
    int quantity
  }
  CUSTOMER ||--o{ ORDER : places
  ORDER ||--|{ LINE_ITEM : contains

requirementDiagram
  direction LR
  requirement reliable {
    id: R1
    text: Requests retain authored meaning
    risk: high
    verifymethod: test
  }
  functionalRequirement edits {
    id: R2
    text: Typed edits preserve all relationships
    risk: medium
    verifymethod: inspection
  }
  element suite {
    type: conformance suite
  }
  reliable - contains -> edits
  suite - verifies -> edits

classDiagram
  Animal <|-- Dog
  Animal <|-- Cat
  Animal : +String name
  Animal : +int age
  Animal : +eat()
  class Dog {
    +bark()
  }
  class Cat {
    +meow()
  }

