---
title: Secure gateway release
---
kanban
  backlog[Backlog]
    schema[Agree API schema]@{ assigned: "Maya", priority: "High", ticket: "GW-201" }
    limits[Define rate limits]@{ assigned: "Owen", priority: "Medium" }
    baseline[Capture load baseline]@{ assigned: "Iris", priority: "Low", ticket: "GW-205" }
  active[In progress]
    replay[Block replayed events]@{ assigned: "Maya", priority: "High", ticket: "GW-208" }
    metrics[Add delivery metrics]@{ assigned: "Noah", priority: "Medium", ticket: "GW-209" }
  review[Validation]
    rehearsal[Run failure rehearsal]@{ assigned: "Iris", priority: "Very High", ticket: "GW-210" }
    accessibility[Review accessibility]@{ assigned: "Owen", priority: "Low", ticket: "GW-211" }
  done[Released]
    framing[Document wire format]@{ assigned: "Noah", priority: "Very Low", ticket: "GW-190" }
    threat[Review threat model]@{ assigned: "Maya", priority: "Medium", ticket: "GW-191" }

requirementDiagram
  requirement reliable {
    id: R1
    text: Preserve authored meaning
    risk: high
    verifymethod: test
  }
  element suite {
    type: conformance suite
  }
  suite - verifies -> reliable
  suite - traces -> reliable

